package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	num := false
	var files []string
	for _, a := range os.Args[1:] {
		if a == "-n" {
			num = true
		} else {
			files = append(files, a)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	status := 0
	n := 0
	emit := func(data []byte) {
		if !num {
			w.Write(data)
			return
		}
		s := string(data)
		if s == "" {
			return
		}
		if !strings.HasSuffix(s, "\n") {
			s += "\n"
		}
		for len(s) > 0 {
			i := strings.IndexByte(s, '\n')
			n++
			fmt.Fprintf(w, "%6d\t%s\n", n, s[:i])
			s = s[i+1:]
		}
	}
	if len(files) == 0 {
		d, _ := io.ReadAll(os.Stdin)
		emit(d)
	}
	for _, f := range files {
		d, err := os.ReadFile(f)
		if err != nil {
			fmt.Fprintf(w, "cat: %s: No such file\n", f)
			status = 1
			continue
		}
		emit(d)
	}
	w.Flush()
	os.Exit(status)
}
